import * as React from "react"

function ColorChangingGradientButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="color-changing-gradient-button"
      className={className}
      {...props}
    >
      <div className="flex justify-center">
        <button className="rounded-md bg-gradient-to-r from-cyan-500 to-blue-500 px-6 py-3 text-white hover500 hover500">
          Let's Go
